# -*- coding: utf-8 -*-
"""Code generated by Visual Paradigm (Tools > Code > Instant Generator, Java, model folder "4 Design") against the
implemented code.

Input
  docs/evidence/vp_codegen/**/*.java   the skeleton VP wrote from the design model of section 4.4 (bodies throw
                                       UnsupportedOperationException); VP prefixes the packages with "__Design"
                                       because the model folder is named "4 Design"
  app/target/classes                   compiled classes (run "mvn -q compile" first), read with javap
  app/src/main/resources/static/js/view/*.js   the view classes (the design's view package runs in the browser)

Checks: every generated class exists in the same package, every generated field is a field (or a derived getter) of
the same type, every generated method exists with the same parameter types and return type; for view classes the
method exists in the JS class with the same number of parameters. Association ends that VP writes as Vector<T> are
compared as List<T>. Exit code = number of problems.
"""
import re
import sys
from collections import defaultdict
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from design_vs_code import ROOT, javap_package, js_views, same_type, split_params  # noqa: E402

GEN = ROOT / "docs" / "evidence" / "vp_codegen"
MOD = r"(?:public |protected |private |static |final |abstract )*"


def norm(t):
    """Undo what the Instant Generator does to type names: the comma of Map<Integer, Product> becomes "__", the
    wildcard of List<?> becomes "_" (both are not Java identifiers), association ends are Vector<T>."""
    t = re.sub(r"\bVector<", "List<", t.strip())
    t = t.replace("__", ",")
    return re.sub(r"(?<=[<,])_(?=[>,])", "?", t)


def same_param(gen, code):
    # a varargs parameter of the model (Role...) is written as Object by the Instant Generator
    return same_type(gen, code) or gen == "Object" and code.endswith("...")


def parse(f):
    text = f.read_text(encoding="utf-8")
    pkg = re.search(r"^package ([\w.]+);", text, re.M).group(1).replace("__Design.", "")
    cm = re.search(r"^public (?:abstract )?(class|interface|enum) (\w+)", text, re.M)
    kind, name = cm.group(1), cm.group(2)
    fields, methods = {}, defaultdict(list)
    body = text[cm.end():]
    if kind == "enum":
        literals = body.split(";", 1)[0]
        for lit in re.findall(r"\b([A-Z][A-Z0-9_]*)\b", literals):
            fields[lit] = name
    for line in body.splitlines():
        if line.startswith("\t\t") or not line.startswith("\t"):
            continue   # VP indents declarations with one tab; two tabs are method bodies
        s = line.strip()
        mm = re.match(MOD + r"(?:<.*?> )?([\w<>\[\], .?]+?) (\w+)\((.*)\)\s*(?:\{|;)$", s)
        if mm and mm.group(2) != name:
            params = [norm(" ".join(p.split()[:-1])) for p in split_params(mm.group(3))]
            methods[mm.group(2)].append((params, norm(mm.group(1))))
            continue
        mf = re.match(MOD + r"([\w<>\[\], .?]+?) (\w+)(?: = .*)?;$", s)
        if mf and "(" not in s:
            fields[mf.group(2)] = norm(mf.group(1))
    return pkg, kind, name, fields, methods


def main():
    problems, checked = [], defaultdict(int)
    code, views = {}, js_views()
    files = sorted(GEN.rglob("*.java"))
    for f in files:
        pkg, kind, cls, fields, methods = parse(f)
        rel = f.relative_to(GEN).as_posix()
        if pkg.endswith(".view"):
            js = views.get(cls)
            checked["view classes"] += 1
            if js is None:
                problems.append(f"{rel}: view class {cls} has no JS module")
                continue
            for op, sigs in methods.items():
                for params, _ in sigs:
                    checked["view operations"] += 1
                    if op not in js:
                        problems.append(f"{cls}.{op}() generated, missing in the JS view")
                    elif len(js[op][0]) != len(params):
                        problems.append(f"{cls}.{op}: generated with {len(params)} parameters, {js[op][1]} has {len(js[op][0])}")
            continue
        if pkg not in code:
            code[pkg] = javap_package(pkg)
        c = code[pkg].get(cls)
        checked["classes"] += 1
        if c is None:
            problems.append(f"{rel}: class {pkg}.{cls} not found in the compiled code")
            continue
        if kind != c["kind"] and not (kind == "class" and c["kind"] == "record"):
            problems.append(f"{cls}: generated as {kind}, the code has a {c['kind']}")
        for a, typ in fields.items():
            checked["fields"] += 1
            if a in c["fields"]:
                if typ and not same_type(typ, c["fields"][a]):
                    problems.append(f"{cls}.{a}: generated type {typ}, code type {c['fields'][a]}")
            elif not (a in c["methods"] or ("get" + a[0].upper() + a[1:]) in c["methods"] or ("is" + a[0].upper() + a[1:]) in c["methods"]):
                problems.append(f"{cls}.{a}: generated field not found in the code")
        for op, sigs in methods.items():
            for params, ret in sigs:
                checked["methods"] += 1
                if op not in c["methods"]:
                    problems.append(f"{cls}.{op}({', '.join(params)}): generated method not found in the code")
                    continue
                match = [m for m in c["methods"][op] if len(m[0]) == len(params) and all(same_param(w, g) for w, g in zip(params, m[0]))]
                if not match:
                    got = " | ".join(f"({', '.join(p)}) : {rt}" for p, rt in c["methods"][op])
                    problems.append(f"{cls}.{op}({', '.join(params)}): parameters differ, code has {got}")
                elif ret and ret != "void" and not any(same_type(ret, m[1]) for m in match):
                    problems.append(f"{cls}.{op}: generated return {ret}, code returns {match[0][1]}")
    for p in problems:
        print("FAIL " + p)
    print(f"{len(files)} generated files; checked " + ", ".join(f"{v} {k}" for k, v in checked.items()))
    print(f"{len(problems)} problems" if problems else "the code implements every class, field and method that VP generated")
    return len(problems)


if __name__ == "__main__":
    sys.exit(min(main(), 100))
